describe('Protected Page Authentication Redirect', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should redirect unauthenticated user to login when accessing protected page', () => {
    // Intercept the protected page request
    cy.intercept('GET', '/api/dashboard').as('dashboardRequest');

    // Attempt to access the protected page without authentication
    cy.get('[data-testid="dashboard-link"]').click();

    // Wait for the intercepted request
    cy.wait('@dashboardRequest');

    // Verify the user is redirected to login page
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-page"]').should('be.visible');

    // Verify login page contains appropriate error message
    cy.get('[data-testid="error-message"]').should('contain', 'Please log in to access this page');

    // Verify login button is visible
    cy.get('[data-testid="login-button"]').should('be.visible');
  });

  it('should handle edge case where user is already logged in and tries to access protected page', () => {
    // Mock successful authentication
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 200,
      body: { token: 'valid-token' }
    }).as('loginSuccess');

    // Mock protected page request
    cy.intercept('GET', '/api/dashboard').as('dashboardRequest');

    // Login as a user
    cy.get('[data-testid="login-form"]').within(() => {
      cy.get('[data-testid="email-input"]').type('user@example.com');
      cy.get('[data-testid="password-input"]').type('password123');
      cy.get('[data-testid="login-button"]').click();
    });

    // Wait for login success
    cy.wait('@loginSuccess');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-content"]').should('be.visible');

    // Verify user is not redirected back to login
    cy.url().should('not.include', '/login');

    // Verify protected page content is displayed
    cy.get('[data-testid="dashboard-title"]').should('contain', 'Dashboard');
  });
});
